package com.seachartingquesthelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Covers the smart-sort design decisions in {@link SeaChartTaskSorter}: the last task in a
 * nearly-finished sea should jump the queue locally, but never at the cost of a cross-map
 * detour, and busy seas must degrade to plain nearest-first.
 *
 * <p>Tasks are picked from the real enum by sea <i>dynamically</i> (never by hardcoded sea
 * constants), so these tests survive a future correction of {@link SeaChartSea}'s data.
 *
 * <p>Keyed by {@link SeaChartSea} (the true ~70 individual seas), not {@link SeaChartRegion} (the
 * 7 broad oceans) -- an earlier version of {@link SeaChartTaskSorter} used the region, which meant
 * "remaining" almost never dropped low enough within an entire ocean to trigger a meaningful
 * bonus. See {@link SeaChartTaskSorter}'s class Javadoc.
 */
public class SeaChartTaskSorterTest
{
	@Test
	public void lastTaskClaimsFullBonusAndBusySeaClaimsAlmostNone()
	{
		// remaining=1 -> the whole avoided-return-trip bonus; remaining=40 -> a negligible share.
		assertEquals(500 - SeaChartTaskSorter.COMPLETION_BONUS_TILES,
			SeaChartTaskSorter.effectiveDistance(500, 1), 0.001);
		assertEquals(500 - SeaChartTaskSorter.COMPLETION_BONUS_TILES / 40,
			SeaChartTaskSorter.effectiveDistance(500, 40), 0.001);
		// A nonsense remaining count of 0 must not divide by zero or over-reward.
		assertEquals(SeaChartTaskSorter.effectiveDistance(500, 1),
			SeaChartTaskSorter.effectiveDistance(500, 0), 0.001);
	}

	@Test
	public void lastTaskInSeaOutranksSimilarlyDistantTaskInBusySea()
	{
		SeaChartTask lastInSea = SeaChartTask.values()[0];
		SeaChartTask inBusySea = taskInDifferentSea(lastInSea);

		// The busy-sea task is even slightly CLOSER, but the last-remaining task should win.
		SeaChartTaskRow lastRow = new SeaChartTaskRow(lastInSea, 500, true, false, false);
		SeaChartTaskRow busyRow = new SeaChartTaskRow(inBusySea, 450, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(busyRow, lastRow));
		SeaChartTaskSorter.sort(rows, progress(lastInSea.getSea(), 1, inBusySea.getSea(), 30));

		assertEquals(lastInSea, rows.get(0).getTask());
	}

	@Test
	public void proximityIsTheTiebreakWhenCompletionStatusIsEqual()
	{
		SeaChartTask near = SeaChartTask.values()[0];
		SeaChartTask far = taskInSameSea(near);

		SeaChartTaskRow nearRow = new SeaChartTaskRow(near, 200, true, false, false);
		SeaChartTaskRow farRow = new SeaChartTaskRow(far, 300, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(farRow, nearRow));
		SeaChartTaskSorter.sort(rows, progress(near.getSea(), 10, near.getSea(), 10));

		assertEquals(near, rows.get(0).getTask());
	}

	@Test
	public void proximityDominatesBetweenTwoBusySeas()
	{
		SeaChartTask near = SeaChartTask.values()[0];
		SeaChartTask far = taskInDifferentSea(near);

		// Both seas have plenty remaining; the small difference in remaining counts (25 vs 30)
		// must not overcome a 200-tile proximity edge -- this is where nearest-first should hold.
		SeaChartTaskRow nearRow = new SeaChartTaskRow(near, 100, true, false, false);
		SeaChartTaskRow farRow = new SeaChartTaskRow(far, 300, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(farRow, nearRow));
		SeaChartTaskSorter.sort(rows, progress(near.getSea(), 30, far.getSea(), 25));

		assertEquals(near, rows.get(0).getTask());
	}

	@Test
	public void completionBonusIsBoundedSoLastTaskNeverForcesAHugeDetour()
	{
		SeaChartTask lastInSea = SeaChartTask.values()[0];
		SeaChartTask inBusySea = taskInDifferentSea(lastInSea);

		// The last task in its sea is a 2000-tile cross-map sail; a busy-sea task is right here.
		// The bonus is capped at ~one inter-sea leg, so the nearby task must still win.
		SeaChartTaskRow lastRow = new SeaChartTaskRow(lastInSea, 2000, true, false, false);
		SeaChartTaskRow busyRow = new SeaChartTaskRow(inBusySea, 100, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(lastRow, busyRow));
		SeaChartTaskSorter.sort(rows, progress(lastInSea.getSea(), 1, inBusySea.getSea(), 30));

		assertEquals(inBusySea, rows.get(0).getTask());
	}

	@Test
	public void exactTiesFallBackToStableTaskIdOrder()
	{
		SeaChartTask first = SeaChartTask.values()[0];
		SeaChartTask second = taskInSameSea(first);
		assertTrue(first.getTaskId() < second.getTaskId());

		SeaChartTaskRow firstRow = new SeaChartTaskRow(first, 250, true, false, false);
		SeaChartTaskRow secondRow = new SeaChartTaskRow(second, 250, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(secondRow, firstRow));
		SeaChartTaskSorter.sort(rows, progress(first.getSea(), 5, first.getSea(), 5));

		assertEquals(first, rows.get(0).getTask());
		assertEquals(second, rows.get(1).getTask());
	}

	@Test
	public void missingSeaProgressMeansNoBonusPureProximity()
	{
		SeaChartTask a = SeaChartTask.values()[0];
		SeaChartTask b = taskInDifferentSea(a);

		SeaChartTaskRow aRow = new SeaChartTaskRow(a, 400, true, false, false);
		SeaChartTaskRow bRow = new SeaChartTaskRow(b, 300, true, false, false);

		List<SeaChartTaskRow> rows = new ArrayList<>(Arrays.asList(aRow, bRow));
		SeaChartTaskSorter.sort(rows, new EnumMap<>(SeaChartSea.class));

		assertEquals(b, rows.get(0).getTask());
		assertEquals(a, rows.get(1).getTask());
	}

	private static Map<SeaChartSea, SeaChartSeaProgress> progress(
		SeaChartSea seaA, int remainingA, SeaChartSea seaB, int remainingB)
	{
		Map<SeaChartSea, SeaChartSeaProgress> progress = new EnumMap<>(SeaChartSea.class);
		// complete=0, total=remaining -> getRemaining() == remaining; only remaining matters here.
		progress.put(seaA, new SeaChartSeaProgress(0, remainingA));
		progress.put(seaB, new SeaChartSeaProgress(0, remainingB));
		return progress;
	}

	private static SeaChartTask taskInDifferentSea(SeaChartTask other)
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			if (task.getSea() != other.getSea())
			{
				return task;
			}
		}
		throw new AssertionError("all tasks share one sea -- test setup impossible");
	}

	private static SeaChartTask taskInSameSea(SeaChartTask other)
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			if (task != other && task.getSea() == other.getSea())
			{
				return task;
			}
		}
		throw new AssertionError("no second task in " + other.getSea() + " -- test setup impossible");
	}
}

package com.seachartingquesthelper;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * End-to-end coverage of the automatic stage-two route re-target through the real plugin event
 * handlers: receive the verbatim in-game trigger message as a {@link ChatMessage}, and verify the
 * plugin posts a Shortest Path {@link PluginMessage} carrying the correct location -- with no
 * manual re-click. Collaborators are mocked; the decision logic under test is real.
 *
 * <p>Weather is three-phase: collecting the station (from the troll, at the primary location)
 * re-targets to the secondary (search) location; the return-success message re-targets back to
 * primary. Current duck is two-phase: release re-targets from primary to secondary and stays
 * there -- there's no return leg.
 *
 * <p>Current duck's trigger is the release message ("You release your current duck..."), fired
 * at task start -- not the arrival message ("...comes to a stop") -- since the destination is
 * static, known task data and useful to route to immediately, before the player has already
 * arrived.
 *
 * <p><b>{@link #duckReleaseMessageAutoRetargetsRouteWithNoPriorPanelClickAtAll} is the live-bug
 * regression test:</b> an earlier version only re-targeted when the resolved task was already
 * the Shortest Path route's current target -- requiring the player to have clicked that exact
 * task's panel row first. Confirmed via a real play session, this almost never happens: a player
 * just sails up to a duck directly. That test exercises exactly that scenario (no
 * {@code onTaskClicked} call at all) and would have caught the bug before it shipped.
 *
 * <p><b>{@link #weatherReturnMessageAutoRetargetsRouteBackToPrimaryLocation} is the second
 * live-bug regression test:</b> an earlier version treated Weather as two-phase and pointed the
 * return message at the secondary location, sending the player away from the troll they'd just
 * been told to return to. Confirmed via direct player report (Current duck worked, Weather
 * didn't) -- consistent with only Weather having this extra return-to-primary leg.
 */
public class SeaChartingQuestHelperPluginRetargetTest
{
	private static final String WEATHER_COLLECTED_MESSAGE = "The troll hands you a portable weather station.";

	private static final String WEATHER_RETURN_MESSAGE =
		"You find a spot where the winds have dropped. You fill the station's log and your"
			+ " charts with interesting data. You should now return to Meaty Aura Logist where"
			+ " she gave you the weather station.";

	private static final String DUCK_MESSAGE =
		"You release your current duck and he begins tracking the currents...";

	private SeaChartingQuestHelperPlugin plugin;
	private Client client;
	private EventBus eventBus;
	private Player player;

	@Before
	public void setUp() throws Exception
	{
		plugin = new SeaChartingQuestHelperPlugin();
		client = mock(Client.class);
		eventBus = mock(EventBus.class);

		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		SeaChartingQuestHelperConfig config = mock(SeaChartingQuestHelperConfig.class);
		when(config.shortestPathIntegration()).thenReturn(true);

		// Note: the mocked client returns 0 for every varbit, so every task reads incomplete.

		// Player stands in the top-level world; position is set per test.
		player = mock(Player.class);
		WorldView topLevel = mock(WorldView.class);
		when(topLevel.isTopLevel()).thenReturn(true);
		when(player.getWorldView()).thenReturn(topLevel);
		when(client.getLocalPlayer()).thenReturn(player);

		inject("client", client);
		inject("clientThread", clientThread);
		inject("eventBus", eventBus);
		inject("config", config);
	}

	@Test
	public void weatherCollectedMessageAutoRetargetsClickedRouteToSecondaryLocation() throws Exception
	{
		SeaChartTask weather = firstTaskOfType(SeaChartTaskType.WEATHER);
		standNear(weather.getLocation());

		clickTask(weather);
		plugin.onChatMessage(gameMessage(WEATHER_COLLECTED_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(2);
		assertEquals("click routes to the primary location", weather.getLocation(), targets.get(0));
		assertEquals("collected signal re-routes to the secondary location, hands-free",
			weather.getSecondaryLocation(), targets.get(1));
	}

	@Test
	public void weatherReturnMessageAutoRetargetsRouteBackToPrimaryLocation() throws Exception
	{
		SeaChartTask weather = firstTaskOfType(SeaChartTaskType.WEATHER);
		standNear(weather.getLocation());

		plugin.onChatMessage(gameMessage(WEATHER_COLLECTED_MESSAGE));
		plugin.onChatMessage(gameMessage(WEATHER_RETURN_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(2);
		assertEquals("collected signal routes to the secondary (search) location",
			weather.getSecondaryLocation(), targets.get(0));
		assertEquals("return signal routes BACK to the primary (troll) location, hands-free",
			weather.getLocation(), targets.get(1));
	}

	@Test
	public void duckReleaseMessageAutoRetargetsClickedRouteToEndPoint() throws Exception
	{
		SeaChartTask duck = firstTaskOfType(SeaChartTaskType.CURRENT_DUCK);
		standNear(duck.getLocation());

		clickTask(duck);
		plugin.onChatMessage(gameMessage(DUCK_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(2);
		assertEquals(duck.getLocation(), targets.get(0));
		assertEquals(duck.getSecondaryLocation(), targets.get(1));
	}

	/**
	 * The live-bug scenario: the player never clicked ANY panel row -- they just sailed up to the
	 * duck in-game and released it. There is no prior Shortest Path route at all when the release
	 * message fires. The plugin must still post the route target automatically, exactly as if the
	 * player had clicked this task's row -- just aimed at the secondary (destination) location.
	 */
	@Test
	public void duckReleaseMessageAutoRetargetsRouteWithNoPriorPanelClickAtAll() throws Exception
	{
		SeaChartTask duck = firstTaskOfType(SeaChartTaskType.CURRENT_DUCK);
		standNear(duck.getLocation());

		// No clickTask(...) call anywhere -- the route has never been set.
		plugin.onChatMessage(gameMessage(DUCK_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(1);
		assertEquals(duck.getSecondaryLocation(), targets.get(0));
	}

	/** Same live-bug scenario, for Weather's collected signal. */
	@Test
	public void weatherCollectedMessageAutoRetargetsRouteWithNoPriorPanelClickAtAll() throws Exception
	{
		SeaChartTask weather = firstTaskOfType(SeaChartTaskType.WEATHER);
		standNear(weather.getLocation());

		plugin.onChatMessage(gameMessage(WEATHER_COLLECTED_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(1);
		assertEquals(weather.getSecondaryLocation(), targets.get(0));
	}

	/**
	 * Re-targeting is unconditional: even if the route currently points at a completely
	 * unrelated task (clicked earlier, or left over from a previous session), a stage-two signal
	 * for a different task still re-targets the route -- exactly like clicking that task's row
	 * would. There is no "must already be the active route target" gate any more (see class
	 * Javadoc: that gate was the bug).
	 */
	@Test
	public void weatherCollectedMessageRedirectsARouteEvenIfPreviouslyAimedAtAnUnrelatedTask() throws Exception
	{
		SeaChartTask weather = firstTaskOfType(SeaChartTaskType.WEATHER);
		SeaChartTask unrelated = firstTaskOfType(SeaChartTaskType.SPYGLASS);
		standNear(weather.getLocation());

		clickTask(unrelated);
		plugin.onChatMessage(gameMessage(WEATHER_COLLECTED_MESSAGE));

		List<WorldPoint> targets = capturePostedTargets(2);
		assertEquals(unrelated.getLocation(), targets.get(0));
		assertEquals(weather.getSecondaryLocation(), targets.get(1));
	}

	@Test
	public void clickingATaskAlreadyInStageTwoRoutesStraightToItsSecondaryLocation() throws Exception
	{
		SeaChartTask weather = firstTaskOfType(SeaChartTaskType.WEATHER);
		standNear(weather.getLocation());

		// Collected signal arrives first (auto-posts to the secondary location -- see the
		// no-prior-click test above), then a later click on the same row should route there too,
		// not the primary.
		plugin.onChatMessage(gameMessage(WEATHER_COLLECTED_MESSAGE));
		clickTask(weather);

		List<WorldPoint> targets = capturePostedTargets(2);
		assertEquals(weather.getSecondaryLocation(), targets.get(0));
		assertEquals(weather.getSecondaryLocation(), targets.get(1));
	}

	private void standNear(WorldPoint location)
	{
		when(player.getWorldLocation()).thenReturn(new WorldPoint(location.getX() + 1, location.getY() + 1, 0));
	}

	private List<WorldPoint> capturePostedTargets(int expectedPosts)
	{
		ArgumentCaptor<PluginMessage> captor = ArgumentCaptor.forClass(PluginMessage.class);
		verify(eventBus, times(expectedPosts)).post(captor.capture());

		java.util.List<WorldPoint> targets = new java.util.ArrayList<>();
		for (PluginMessage message : captor.getAllValues())
		{
			assertEquals("shortestpath", message.getNamespace());
			assertEquals("path", message.getName());
			targets.add((WorldPoint) message.getData().get("target"));
		}
		return targets;
	}

	private static ChatMessage gameMessage(String message)
	{
		return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", message, null, 0);
	}

	/** Drives the panel's click callback (private on the plugin) reflectively. */
	private void clickTask(SeaChartTask task) throws Exception
	{
		Method onTaskClicked = SeaChartingQuestHelperPlugin.class
			.getDeclaredMethod("onTaskClicked", SeaChartTask.class);
		onTaskClicked.setAccessible(true);
		onTaskClicked.invoke(plugin, task);
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field field = SeaChartingQuestHelperPlugin.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private static SeaChartTask firstTaskOfType(SeaChartTaskType type)
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			if (task.getType() == type)
			{
				return task;
			}
		}
		throw new AssertionError("No task of type " + type);
	}
}

package com.seachartingquesthelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import org.junit.Test;

/**
 * Data-integrity checks for {@link SeaChartSea}: every task must resolve to exactly one of the 70
 * real seas, and each sea's {@link SeaChartSea#getRegion()} must agree with the independently
 * verified {@link SeaChartTask#getRegion()} (sourced from {@link SeaChartRegion}, which folds the
 * wiki's "Bonus charts" tag and splits the Western Ocean's two geographic clusters) -- confirming
 * the two data sets, extracted from the same raw wiki table by two different passes, agree
 * task-by-task rather than just at the aggregate-count level.
 */
public class SeaChartSeaTest
{
	@Test
	public void everyTaskResolvesToASea()
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertNotNull(task + " has no sea", task.getSea());
		}
	}

	@Test
	public void thereAreExactly70RealSeas()
	{
		assertEquals(70, SeaChartSea.values().length);
	}

	@Test
	public void everySeasRegionAgreesWithItsTasksIndependentlyComputedRegion()
	{
		// Cross-checks SeaChartSea's per-sea region assignment against SeaChartTask#getRegion()
		// (SeaChartRegion's already-verified per-task resolution) for every single task, not just
		// a spot check -- both ultimately derive from the same wiki table but were built as
		// separate passes, so this confirms they didn't diverge anywhere.
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertEquals(task + " (" + task.getSea() + ")'s region should match its own getRegion()",
				task.getRegion(), task.getSea().getRegion());
		}
	}

	@Test
	public void knownSeasHaveTheExpectedRegion()
	{
		// A handful of well-known place-name seas, cross-checked directly against the wiki.
		assertEquals(SeaChartRegion.NORTHERN, SeaChartSea.SHIVERWAKE_EXPANSE.getRegion());
		assertEquals(SeaChartRegion.SHROUDED, SeaChartSea.BACKWATER.getRegion());
		assertEquals(SeaChartRegion.WESTERN_TIRANNWN, SeaChartSea.PORTH_GWENITH.getRegion());
		assertEquals(SeaChartRegion.WESTERN_KOUREND, SeaChartSea.GREAT_SOUND.getRegion());
		assertEquals(SeaChartRegion.SUNSET, SeaChartSea.SUNSET_BAY.getRegion());
		assertEquals(SeaChartRegion.ARDENT, SeaChartSea.KHARAZI_STRAIT.getRegion());
	}
}

package com.seachartingquesthelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Test;

public class SeaChartTaskTest
{
	@Test
	public void has358Tasks()
	{
		// The whole point of this plugin -- confirm we mirrored the full task table.
		assertEquals(358, SeaChartTask.values().length);
	}

	@Test
	public void taskIdsAreSequentialAndMatchOrdinal()
	{
		int expected = 0;
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertEquals(expected, task.getTaskId());
			assertEquals(expected, task.ordinal());
			expected++;
		}
	}

	@Test
	public void varbitsAreUnique()
	{
		Set<Integer> seen = new HashSet<>();
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertTrue("duplicate completion varbit for " + task, seen.add(task.getVarbit()));
		}
	}

	@Test
	public void byVarbitLooksUpTheOwningTask()
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertEquals(task, SeaChartTask.byVarbit(task.getVarbit()));
		}
	}

	@Test
	public void everyTaskHasEitherAnObjectOrNpcTarget()
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertTrue(task + " has neither an object nor an npc id",
				task.getObjectId() != -1 || task.getNpcId() != -1);
		}
	}

	@Test
	public void rainbowReefMermaidGuideIsLevel72()
	{
		// Spot-check named in the design notes: Rainbow Reef's mermaid guide task requires 72
		// Sailing, one of the highest level gates in the table.
		SeaChartTask task = SeaChartTask.TASK_52;
		assertEquals(SeaChartTaskType.MERMAID_GUIDE, task.getType());
		assertEquals(72, task.getLevel());
		assertEquals("Rainbow Reef", task.getTaskName());
	}

	@Test
	public void questForCoversEveryTaskType()
	{
		for (SeaChartTaskType type : SeaChartTaskType.values())
		{
			assertNotNull(SeaChartRequirements.questFor(type));
		}
	}

	@Test
	public void levelsAreNonNegative()
	{
		for (SeaChartTask task : SeaChartTask.values())
		{
			assertTrue(task + " has a negative level requirement", task.getLevel() >= 0);
		}
	}

	@Test
	public void everyTaskHasARegionAndPortHint()
	{
		// Region assignment is sourced directly from the OSRS Wiki's per-task ocean/sea tags (see
		// SeaChartRegion's Javadoc); the nearest-teleport hint is per-sea (SeaChartSea), not
		// per-region -- see SeaChartSeaTest for the sea-level equivalent of this check. Every one
		// of the 358 tasks must still resolve to some region and some non-blank port hint, since
		// the panel always renders a "Nearest: ..." line.
		for (SeaChartTask task : SeaChartTask.values())
		{
			SeaChartRegion region = task.getRegion();
			assertNotNull(task + " has no region", region);
			assertTrue(task + "'s sea has a blank port hint", !task.getSea().getNearestPort().trim().isEmpty());
		}
	}

	@Test
	public void regionCountsMatchWikiOceanTotals()
	{
		// Every task's region comes from a 358-entry lookup table built from the wiki's per-task
		// ocean/sea tags (not guessed index ranges) -- these per-region tallies are a strong
		// regression check: any future edit that nudges even one task into the wrong region will
		// change one of these counts.
		Map<SeaChartRegion, Integer> counts = new EnumMap<>(SeaChartRegion.class);
		for (SeaChartTask task : SeaChartTask.values())
		{
			counts.merge(task.getRegion(), 1, Integer::sum);
		}

		assertEquals(Integer.valueOf(87), counts.get(SeaChartRegion.ARDENT));
		assertEquals(Integer.valueOf(38), counts.get(SeaChartRegion.UNQUIET));
		assertEquals(Integer.valueOf(78), counts.get(SeaChartRegion.SHROUDED));
		assertEquals(Integer.valueOf(14), counts.get(SeaChartRegion.SUNSET));
		assertEquals(Integer.valueOf(44), counts.get(SeaChartRegion.WESTERN_KOUREND));
		assertEquals(Integer.valueOf(22), counts.get(SeaChartRegion.WESTERN_TIRANNWN));
		assertEquals(Integer.valueOf(75), counts.get(SeaChartRegion.NORTHERN));
	}

	@Test
	public void westernOceanTasksAreNotMislabeledNorthern()
	{
		// Regression test for the original bug: an earlier version of SeaChartRegion guessed ocean
		// boundaries from index ranges and put every real Western Ocean place name (Great Sound,
		// Crabclaw Bay, Gulf of Kourend, Hosidian Sea, Pilgrims' Passage, Crystal Sea, Litus Lucis,
		// Moonshadow, Vagabonds Rest, Porth Neigwl, Piscatoris Sea, Porth Gwenith, Tirannwn Bight)
		// into "Northern+Misc" instead. Spot-check tasks from both real Western clusters.

		// Kourend-side cluster (Great Kourend / Land's End / Hosidius).
		assertEquals(SeaChartRegion.WESTERN_KOUREND, SeaChartTask.TASK_153.getRegion()); // Crystal Sea
		assertEquals(SeaChartRegion.WESTERN_KOUREND, SeaChartTask.TASK_175.getRegion()); // Gulf of Kourend
